kit.scene('beg', {
  init(kit) {
    this.s = W.shot(kit, {
      id: 'beg', tears: true, back: '<g style="opacity:.3">' + W.lace(70, 160, 70, 960, 14, 9) + W.lace(848, 160, 848, 960, 14, 9) + '</g>',
      cast: [{ who: 'mandodari', x: 420, y: 1480, s: 1.12, flip: true }],
      cam: [1.0, 1.04, 459, 520, 459, 505],
      arm: (t) => 22 + 6 * Math.sin(t * 2.0),
      lines: [[29.9, 32.2, 'मेरी बस एक विनती मान लीजिए…', 0, 0]],
    });
  },
  render(t) { this.s.render(t); },
});
